    nav_store: "Store", store_title: "Store", store_desc: "Free homebrew games, tools and emulators for DS and DSi (Universal-DB catalog). The program you pick goes to roms/NDS/Homebrew on the card and shows up in All Games. The Store on the console uses the same catalog: you can download from there too while the console is connected to Studio.", store_search: "Search…", store_refresh: "Refresh", store_all: "Popular", store_games: "Games", store_tools: "Tools", store_emus: "Emulators", store_apps: "Apps", store_card: "Install to card", store_again: "Install again", store_wifi: "Send to console", store_remove: "Remove", store_installed: "Installed", store_offline: "Could not download the catalog (check the internet connection)", store_n: "{n} programs", store_done: "{t} installed", store_fail: "Could not install", store_space: "Not enough space on the card", store_removed: "{t} removed", store_web: "Project page", store_note: "Catalog: Universal-DB (db.universal-team.net). Programs are downloaded from their authors' pages and each comes with its own license.",
