    boot_title: "Your own boot screen", boot_desc: "Your photo and sound when the console starts. The picture is read once (about 0.05 s) and the display's brightness hardware does the transition, so the menu loads just as fast. Any button skips it. On the console: Settings > Boot animation: Standard / My own / Off.", boot_layout: "Picture", boot_l_top: "Upper screen (lower screen black)", boot_l_span: "One picture across both screens", boot_l_two: "A picture for each screen", boot_pic: "Choose picture", boot_pic2: "Lower screen picture", boot_sound: "Choose sound", boot_nosound: "Remove sound", boot_len: "Length", boot_style: "Transition", boot_s_fade: "From black", boot_s_flash: "From white", boot_save: "Write to card and use", boot_remove: "Remove", boot_sound_new: "New sound: {s} s", boot_sound_card: "Sound on the card ({s} s)", boot_sound_none: "No sound (system sound plays)", boot_sound_cut: "The sound was longer than 5 seconds; the first 5 seconds are used", boot_sound_bad: "This sound file could not be opened", boot_on_card: "Your boot screen is on the card; {n} profiles use it. Click the picture to preview.", boot_hint: "Choose a picture; add a sound if you like (mp3, wav, m4a… up to 5 s).", boot_saved: "Boot screen written to the card (on in {n} profiles)", boot_remove_q: "Delete your boot screen from the card? The console goes back to the standard animation.", boot_removed: "Removed, the standard animation will be used",
